#include <algorithm>
#include <set>
#include <string>
#include <vector>

struct ModInfo { std::string name; std::vector<std::string> needs; };
struct Order { std::vector<std::string> order; std::vector<std::string> missing; std::vector<std::string> cycle; };

Order loadOrder(const std::vector<ModInfo>& mods)
{
    Order o;
    std::set<std::string> present;
    for (const ModInfo& m : mods) present.insert(m.name);

    // Mods that cannot load because something they need (directly or indirectly) is absent.
    std::set<std::string> broken;
    for (bool changed{ true }; changed; )
    {
        changed = false;
        for (const ModInfo& m : mods)
        {
            if (broken.count(m.name)) continue;
            for (const std::string& r : m.needs)
                if (!present.count(r) || broken.count(r)) { broken.insert(m.name); changed = true; break; }
        }
    }

    std::set<std::string> placed;
    std::vector<bool> done(mods.size(), false);
    for (std::size_t i{ 0 }; i < mods.size(); ++i) if (broken.count(mods[i].name)) done[i] = true;
    for (bool progress{ true }; progress; )
    {
        progress = false;
        for (std::size_t i{ 0 }; i < mods.size(); ++i)                 // earliest ready mod in the player's order
        {
            if (done[i]) continue;
            const bool ready{ std::all_of(mods[i].needs.begin(), mods[i].needs.end(), [&](const std::string& r) { return placed.count(r) > 0; }) };
            if (!ready) continue;
            o.order.push_back(mods[i].name);
            placed.insert(mods[i].name);
            done[i] = true;
            progress = true;
            break;                                                    // start again from the front of the list
        }
    }
    o.missing.assign(broken.begin(), broken.end());
    for (std::size_t i{ 0 }; i < mods.size(); ++i) if (!done[i]) o.cycle.push_back(mods[i].name);
    std::sort(o.cycle.begin(), o.cycle.end());
    return o;
}

unitTests:
using N = std::vector<std::string>;
TEST("the example")
{
    const Order o{ loadOrder({ { "ui", { "core" } }, { "core", {} }, { "extra", { "ui", "missing-mod" } }, { "maps", {} } }) };
    CHECK(o.order == N({ "core", "ui", "maps" }));
    CHECK(o.missing == N({ "extra" }));
    CHECK(o.cycle.empty());
}
TEST("no requirements keeps the player's order") { CHECK(loadOrder({ { "c", {} }, { "a", {} }, { "b", {} } }).order == N({ "c", "a", "b" })); }
TEST("a chain") { CHECK(loadOrder({ { "c", { "b" } }, { "b", { "a" } }, { "a", {} } }).order == N({ "a", "b", "c" })); }
TEST("a cycle") { const Order o{ loadOrder({ { "x", { "y" } }, { "y", { "x" } }, { "z", {} } }) }; CHECK(o.order == N({ "z" })); CHECK(o.cycle == N({ "x", "y" })); }
TEST("missing spreads to dependants") { const Order o{ loadOrder({ { "a", { "gone" } }, { "b", { "a" } }, { "c", {} } }) }; CHECK(o.order == N({ "c" })); CHECK(o.missing == N({ "a", "b" })); }
TEST("nothing") { const Order o{ loadOrder({}) }; CHECK(o.order.empty()); CHECK(o.missing.empty()); CHECK(o.cycle.empty()); }

